def kthSmallestPath(destination, k):
    from math import comb
    row, col = destination
    res = []
    for _ in range(row + col):
        if col == 0:
            res.append('V')
            row -= 1
        elif row == 0:
            res.append('H')
            col -= 1
        else:
            hs = comb(row + col - 1, col - 1)
            if k <= hs:
                res.append('H')
                col -= 1
            else:
                res.append('V')
                k -= hs
                row -= 1
    return ''.join(res)
